svg.script:
(function () {
  function colorForState(state) {
    if (state === 'open') return '#7EE787';
    if (state === 'closed') return '#FF7B72';
    return '#FFFFFF';
  }

  function labelTextForState(state) {
    if (state === 'open') return 'OPEN';
    if (state === 'closed') return 'CLOSE';
    return 'OPEN/CLOSE';
  }

  function normalizeState(state) {
    if (state === 'default' || state === 'neutral' || !state) return 'neutral';
    return state;
  }

  function externalStateName(state) {
    return state === 'neutral' ? 'default' : state;
  }

  function normalizeGroupId(id) {
    if (!id) return '';
    return /-control$/.test(id) ? id : (id + '-control');
  }

  function valveIdForGroup(group) {
    if (!group || !group.id) return '';
    return group.id.replace(/-control$/, '');
  }

  function findGroup(id) {
    if (!id) return null;
    return document.getElementById(normalizeGroupId(id)) || document.getElementById(id);
  }

  function notifyPython(group, state) {
    var valveId = valveIdForGroup(group);
    if (!valveId) return;

    try {
      if (window.bridge && typeof window.bridge.valveClicked === 'function') {
        window.bridge.valveClicked(valveId);
      }
    } catch (err) {
      console.log('bridge.valveClicked failed for', valveId, err);
    }

    try {
      window.dispatchEvent(new CustomEvent('xv-state-changed', {
        detail: {
          id: valveId,
          state: externalStateName(state)
        }
      }));
    } catch (err) {
      console.log('custom event dispatch failed for', valveId, err);
    }
  }

  function updateLinkedLabels(group, state) {
    var color = colorForState(state);
    var textValue = labelTextForState(state);
    document.querySelectorAll('.xv-state-label[data-for="' + group.id + '"]').forEach(function (label) {
      var textNode = label.querySelector('.xv-state-text');
      if (!textNode) return;
      textNode.textContent = textValue;
      textNode.setAttribute('fill', color);
      textNode.style.fill = color;
      label.dataset.state = state || 'neutral';
      label.setAttribute('aria-pressed', state === 'open' ? 'true' : 'false');
    });
  }

  function applyState(group, state) {
    state = normalizeState(state);

    var color = null;
    if (state === 'open') color = '#7EE787';
    else if (state === 'closed') color = '#FF7B72';

    group.querySelectorAll('path, rect, line, polyline, polygon, circle, ellipse').forEach(function (node) {
      if (!node.dataset.origFill) node.dataset.origFill = node.getAttribute('fill') || '';
      if (!node.dataset.origStroke) node.dataset.origStroke = node.getAttribute('stroke') || '';
      if (!node.dataset.origStyleFill) node.dataset.origStyleFill = node.style.fill || '';
      if (!node.dataset.origStyleStroke) node.dataset.origStyleStroke = node.style.stroke || '';

      var origFill = node.dataset.origFill;
      var origStroke = node.dataset.origStroke;
      var origStyleFill = node.dataset.origStyleFill;
      var origStyleStroke = node.dataset.origStyleStroke;

      if (!color) {
        if (origFill) node.setAttribute('fill', origFill);
        else node.removeAttribute('fill');

        if (origStroke) node.setAttribute('stroke', origStroke);
        else node.removeAttribute('stroke');

        node.style.fill = origStyleFill;
        node.style.stroke = origStyleStroke;
      } else {
        var nextFill = origFill && origFill.toLowerCase() !== 'none' ? color : 'none';
        var nextStroke = origStroke && origStroke.toLowerCase() !== 'none' ? color : 'none';

        if (nextFill === 'none') node.setAttribute('fill', 'none');
        else node.setAttribute('fill', nextFill);

        if (nextStroke === 'none') node.setAttribute('stroke', 'none');
        else node.setAttribute('stroke', nextStroke);

        node.style.fill = origStyleFill && origStyleFill.toLowerCase() !== 'none' ? color : nextFill;
        node.style.stroke = origStyleStroke && origStyleStroke.toLowerCase() !== 'none' ? color : nextStroke;
      }
    });

    group.dataset.state = state;
    group.setAttribute('aria-pressed', state === 'open' ? 'true' : 'false');
    updateLinkedLabels(group, state);
    return true;
  }

  function toggleState(group, shouldNotifyPython) {
    var current = normalizeState(group.dataset.state || 'neutral');
    var next = current === 'open' ? 'closed' : 'open';
    applyState(group, next);

    if (shouldNotifyPython !== false) {
      notifyPython(group, next);
    }
  }

  function bindToggleTrigger(node, group) {
    if (!node) return;
    node.addEventListener('click', function (ev) {
      ev.preventDefault();
      toggleState(group, true);
    });
    node.addEventListener('keydown', function (ev) {
      if (ev.key === 'Enter' || ev.key === ' ') {
        ev.preventDefault();
        toggleState(group, true);
      }
    });
  }

  function initGroup(group) {
    applyState(group, group.dataset.state || 'neutral');
    bindToggleTrigger(group, group);
    document.querySelectorAll('.xv-state-label[data-for="' + group.id + '"]').forEach(function (label) {
      bindToggleTrigger(label, group);
    });
  }

  function setXVState(id, state) {
    var group = findGroup(id);
    if (!group) {
      console.log('setXVState: group not found for', id);
      return false;
    }
    return applyState(group, state);
  }

  function getXVState(id) {
    var group = findGroup(id);
    if (!group) return null;
    return externalStateName(normalizeState(group.dataset.state || 'neutral'));
  }

  function init() {
    document.querySelectorAll('.xv-control').forEach(initGroup);
  }

  window.setXVState = setXVState;
  window.getXVState = getXVState;

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
